cueCss:
.wt-cue{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.wt-row{position:absolute;left:0;right:0;top:82%;height:10%;display:flex;align-items:center;justify-content:center;gap:calc(1.05*var(--wt-u));padding:0 calc(1.2*var(--wt-u))}
.wt-emblem{position:relative;flex:0 0 calc(5.4*var(--wt-u));width:calc(5.4*var(--wt-u));height:calc(5.4*var(--wt-u));z-index:1}
.wt-trail{position:absolute;right:40%;bottom:4%;width:calc(8*var(--wt-u));height:calc(2.4*var(--wt-u));overflow:visible}
.wt-trail-a,.wt-trail-b{stroke-dasharray:120;stroke-dashoffset:120;opacity:.55}
.wt-trail-a{animation:wt-trail-draw .68s .04s cubic-bezier(.2,.7,.2,1) forwards,wt-trail-out .4s calc(var(--wt-dur) - .4s) forwards}
.wt-trail-b{opacity:.4;animation:wt-trail-draw .72s .1s cubic-bezier(.2,.7,.2,1) forwards,wt-trail-out .4s calc(var(--wt-dur) - .4s) forwards}
.wt-spray{opacity:0;transform-box:fill-box;transform-origin:center;animation:wt-spray .5s .5s cubic-bezier(.16,1.15,.3,1) forwards,wt-spray-out .36s calc(var(--wt-dur) - .4s) forwards}
.wt-ski{width:100%;height:100%;transform-origin:70% 82%;animation:wt-ski-in .66s cubic-bezier(.18,.82,.22,1) forwards,wt-ski-out .4s calc(var(--wt-dur) - .4s) cubic-bezier(.42,0,.8,.2) forwards}
.wt-nod{width:100%;height:100%;transform-origin:50% 78%;animation:wt-nod 1.7s .68s ease-in-out infinite}
.wt-fur{width:100%;height:100%;transform-origin:50% 100%;animation:wt-fur 1.55s .7s ease-in-out infinite}
.wt-mascot{display:block;width:100%;height:100%;overflow:visible}
.wt-glint{transform-box:fill-box;transform-origin:center;opacity:0;animation:wt-glint-flash .5s .48s ease-out forwards,wt-glint-drift 2s 1s ease-in-out infinite}
.wt-copy{position:relative;z-index:2;max-width:calc(70*var(--wt-u));font-family:var(--wt-font);font-size:var(--wt-size);font-weight:700;line-height:1.22;letter-spacing:calc(.085*var(--wt-u));color:#F7F3EC;text-align:center;white-space:normal;overflow-wrap:anywhere;-webkit-font-smoothing:antialiased}
.wt-copy > *,.wt-copy .wt-w{display:inline-block;opacity:0;-webkit-text-stroke:2px #203943;paint-order:stroke fill;text-shadow:0 .35px 0 rgba(255,252,250,.28);animation:wt-frost-in .48s cubic-bezier(.2,.74,.2,1) forwards,wt-frost-out .4s cubic-bezier(.4,0,1,.35) forwards}
.wt-copy > *,.wt-copy .wt-w{animation-delay:calc(.32s + var(--i,0)*.048s),calc(var(--wt-dur) - .4s)}
.wt-copy > *:nth-child(1),.wt-copy .wt-w:nth-child(1){--i:0}
.wt-copy > *:nth-child(2),.wt-copy .wt-w:nth-child(2){--i:1}
.wt-copy > *:nth-child(3),.wt-copy .wt-w:nth-child(3){--i:2}
.wt-copy > *:nth-child(4),.wt-copy .wt-w:nth-child(4){--i:3}
.wt-copy > *:nth-child(5),.wt-copy .wt-w:nth-child(5){--i:4}
.wt-copy > *:nth-child(6),.wt-copy .wt-w:nth-child(6){--i:5}
.wt-copy > *:nth-child(7),.wt-copy .wt-w:nth-child(7){--i:6}
.wt-copy > *:nth-child(8),.wt-copy .wt-w:nth-child(8){--i:7}
.wt-copy > *:nth-child(9),.wt-copy .wt-w:nth-child(9){--i:8}
.wt-copy > *:nth-child(10),.wt-copy .wt-w:nth-child(10){--i:9}
.wt-copy > *:nth-child(11),.wt-copy .wt-w:nth-child(11){--i:10}
.wt-copy > *:nth-child(12),.wt-copy .wt-w:nth-child(12){--i:11}
.wt-copy > *:nth-child(13),.wt-copy .wt-w:nth-child(13){--i:12}
.wt-copy > *:nth-child(14),.wt-copy .wt-w:nth-child(14){--i:13}
.wt-copy > *:nth-child(15),.wt-copy .wt-w:nth-child(15){--i:14}
.wt-copy > *:nth-child(16),.wt-copy .wt-w:nth-child(16){--i:15}
@keyframes wt-ski-in{
  0%{opacity:0;transform:translate3d(calc(-8.2*var(--wt-u)),calc(.5*var(--wt-u)),0) rotate(-16deg)}
  60%{opacity:1;transform:translate3d(calc(.4*var(--wt-u)),0,0) rotate(3.4deg)}
  78%{transform:translate3d(calc(-.12*var(--wt-u)),calc(.16*var(--wt-u)),0) rotate(-1.6deg)}
  100%{opacity:1;transform:translate3d(0,0,0) rotate(0)}
}
@keyframes wt-ski-out{
  to{opacity:0;transform:translate3d(calc(9.2*var(--wt-u)),calc(-.28*var(--wt-u)),0) rotate(11deg)}
}
@keyframes wt-nod{
  0%,100%{transform:rotate(0)}
  30%{transform:rotate(2.4deg)}
  56%{transform:rotate(-1.1deg)}
}
@keyframes wt-fur{
  0%,100%{transform:scale(1,1)}
  42%{transform:scale(1.018,.984)}
  70%{transform:scale(.992,1.01)}
}
@keyframes wt-glint-flash{
  0%{opacity:0}
  40%{opacity:1}
  100%{opacity:.42}
}
@keyframes wt-glint-drift{
  0%{transform:translate(0,0)}
  100%{transform:translate(calc(.28*var(--wt-u)),calc(.04*var(--wt-u)))}
}
@keyframes wt-trail-draw{
  to{stroke-dashoffset:0}
}
@keyframes wt-trail-out{
  to{stroke-dashoffset:-36;opacity:0}
}
@keyframes wt-spray{
  0%{opacity:0;transform:scale(.35) translate(-6px,3px)}
  45%{opacity:.8;transform:scale(1) translate(0,0)}
  100%{opacity:.32;transform:scale(.92)}
}
@keyframes wt-spray-out{
  to{opacity:0;transform:translate(8px,-2px)}
}
@keyframes wt-frost-in{
  0%{opacity:0;transform:translateY(calc(-.42*var(--wt-u)));color:#C5D2D6;text-shadow:0 .35px 0 rgba(255,252,250,.12)}
  58%{opacity:1;color:#E8EEF0;transform:translateY(0)}
  100%{opacity:1;transform:translateY(0);color:#F7F3EC;text-shadow:0 .35px 0 rgba(255,252,250,.28)}
}
@keyframes wt-frost-out{
  to{opacity:0;transform:translateX(calc(4.6*var(--wt-u)));color:#D0DADF;letter-spacing:calc(.2*var(--wt-u));text-shadow:0 .35px 0 rgba(255,252,250,.1)}
}
